import pandas as pd,numpy as np,glob
from scipy.optimize import least_squares
def load(f):
  d=pd.read_csv(f).iloc[::5];return d
D={f:load(f) for f in glob.glob('train/*.csv')+glob.glob('val/*.csv')}
dt=0.005
def sim(p,d):
  Kp,Tw,Tp,Kq,Tv,Tq=p
  th=d.bus_angle_rad.values;V=d.voltage_pu.values;Vs=d.voltage_setpoint_pu.values
  P0=d.active_power_pu.values[0];Q0=d.reactive_power_pu.values[0]
  tf=th[0];Pm=P0;Vm=V[0];Qm=Q0;P=[];Q=[]
  for k in range(len(th)):
    w=(th[k]-tf)/(Tw*377);P.append(Pm);Q.append(Qm)
    tf+=dt*(th[k]-tf)/Tw;Pm+=dt*(P0-Kp*w-Pm)/Tp
    Vm+=dt*(V[k]-Vm)/Tv;Qm+=dt*(Q0+Kq*(Vs[k]-Vm)-Qm)/Tq
  return np.array(P),np.array(Q)
def res(p,fs):
  r=[]
  for f in fs:
    d=D[f];P,Q=sim(p,d);r+=[P-d.active_power_pu.values,Q-d.reactive_power_pu.values]
  return np.concatenate(r)
tr=[f for f in D if 'train' in f]
s=least_squares(res,[17,0.05,0.2,5,0.02,0.1],args=(tr,),bounds=([0,0.006,0.006,0,0.006,0.006],[100,2,5,100,2,5]))
print(s.x)
for f in D:
  d=D[f];P,Q=sim(s.x,d);print(f,np.std(P-d.active_power_pu),np.std(d.active_power_pu),np.std(Q-d.reactive_power_pu),np.std(d.reactive_power_pu))

