import pandas as pd,numpy as np,glob,json
from scipy.optimize import least_squares
D={f:pd.read_csv(f).iloc[::2] for f in glob.glob('train/*.csv')+glob.glob('val/*.csv')}
dt=0.002
def simQ(p,d):
  Tv,Kp,Ki,nq,Tq=p
  V=d.voltage_pu.values;Vs=d.voltage_setpoint_pu.values;Q0=d.reactive_power_pu.values[0]
  Vf=V[0];xi=0;Qm=Q0;Q=np.empty(len(V))
  for k in range(len(V)):
    Q[k]=Qm;e=Vs[k]-Vf-nq*(Qm-Q0)
    Vf+=dt*(V[k]-Vf)/Tv;xi+=dt*Ki*e;Qm+=dt*(Q0+Kp*e+xi-Qm)/Tq
  return Q
def res(p,fs):
  return np.nan_to_num(np.concatenate([simQ(p,D[f])-D[f].reactive_power_pu.values for f in fs]),nan=10)
tr=[f for f in D if 'train' in f]
best=None
for x0 in [[0.02,2,10,0.05,0.05],[0.1,10,50,0.0,0.02],[0.02,0.5,2,0.2,0.2]]:
  s=least_squares(res,x0,args=(tr,),bounds=([0.002,0,0,0,0.002],[2,200,500,2,5]))
  print(list(s.x),s.cost)
  if best is None or s.cost<best.cost: best=s
json.dump(list(best.x),open('pq.json','w'))
for f in D:
  d=D[f];Q=simQ(best.x,d);print(f,np.std(Q-d.reactive_power_pu),np.std(d.reactive_power_pu))

